(function () {
  'use strict';

  // Per-lawyer settings. Everything else is plain HTML (generated by build.py).
  var CONFIG = {
    whatsapp: '201140118038', // international format, no "+"
    defaultMessage: 'السلام عليكم، أرغب في الاستفسار عن خدمات المكتب.',
    timezone: 'Africa/Cairo'
  };

  function waUrl(text) {
    return 'https://wa.me/' + CONFIG.whatsapp + '?text=' + encodeURIComponent(text);
  }

  document.querySelectorAll('[data-wa]').forEach(function (el) {
    el.setAttribute('href', waUrl(el.getAttribute('data-msg') || CONFIG.defaultMessage));
    el.setAttribute('target', '_blank');
    el.setAttribute('rel', 'noopener');
  });

  // WhatsApp-only contact form.
  var form = document.getElementById('waForm');
  if (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var name = form.elements.name;
      if (!name.value.trim()) {
        name.classList.add('invalid');
        name.focus();
        return;
      }
      var text = 'السلام عليكم،\nالاسم: ' + name.value.trim() + '\nالموضوع: ' + form.elements.type.value;
      var msg = form.elements.msg.value.trim();
      if (msg) text += '\nالتفاصيل: ' + msg;
      window.open(waUrl(text), '_blank', 'noopener');
    });
    form.elements.name.addEventListener('input', function () { this.classList.remove('invalid'); });
  }

  // Menu: phone toggle and the "services" dropdown.
  var toggle = document.getElementById('menuToggle');
  var nav = document.getElementById('nav');
  var ddBtn = document.getElementById('ddBtn');
  var ddPanel = document.getElementById('ddPanel');
  var wide = window.matchMedia('(min-width: 900px)');

  function setDropdown(open) {
    if (!ddBtn || !ddPanel) return;
    ddBtn.setAttribute('aria-expanded', String(open));
    ddPanel.hidden = !open;
  }
  function setMenu(open) {
    if (!toggle || !nav) return;
    nav.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', String(open));
    if (!open) setDropdown(false);
  }

  if (toggle && nav) {
    toggle.addEventListener('click', function () { setMenu(!nav.classList.contains('open')); });
  }
  if (ddBtn && ddPanel) {
    ddBtn.addEventListener('click', function () { setDropdown(ddPanel.hidden); });
    document.addEventListener('click', function (e) {
      if (!ddPanel.hidden && !ddPanel.contains(e.target) && !ddBtn.contains(e.target)) setDropdown(false);
    });
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'Escape') return;
      if (!ddPanel.hidden) { setDropdown(false); ddBtn.focus(); }
      else if (nav && nav.classList.contains('open')) { setMenu(false); if (toggle) toggle.focus(); }
    });
    // Open the dropdown when it sits inside the open phone menu and the page is a service page.
    ddPanel.addEventListener('click', function (e) {
      if (e.target.closest('a')) setMenu(false);
    });
  }
  if (nav) {
    nav.addEventListener('click', function (e) {
      var a = e.target.closest('a');
      if (a && !a.closest('.dd-panel')) setMenu(false);
    });
  }
  if (wide.addEventListener) {
    wide.addEventListener('change', function () { setMenu(false); setDropdown(false); });
  }

  // Hero portrait: show it only when the file exists, so the page works before the photo is added.
  var photo = document.getElementById('heroPhoto');
  var hero = document.getElementById('hero');
  if (photo && hero) {
    var show = function () { photo.hidden = false; hero.classList.add('has-photo'); };
    if (photo.complete && photo.naturalWidth) show();
    else photo.addEventListener('load', show);
  }

  // Opening hours: highlight today's row (Cairo time). The office is closed on Friday only.
  function cairoDay() {
    try {
      var w = new Intl.DateTimeFormat('en-US', { timeZone: CONFIG.timezone, weekday: 'short' }).format(new Date());
      return { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[w];
    } catch (err) {
      return new Date().getDay();
    }
  }
  var today = document.querySelector('#hoursList [data-day="' + cairoDay() + '"]');
  if (today) {
    today.classList.add('today');
    var s = today.querySelector('.s');
    if (s && !today.classList.contains('off')) s.textContent = 'اليوم';
  }

  var year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
})();
